import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ética Tecnológica y Límites de Seguridad","description":"","frontmatter":{},"headers":[],"relativePath":"es/68-技术伦理与安全边界.md","filePath":"es/68-技术伦理与安全边界.md"}'),n={name:"es/68-技术伦理与安全边界.md"};function d(l,e,t,r,c,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="etica-tecnologica-y-limites-de-seguridad" tabindex="-1">Ética Tecnológica y Límites de Seguridad <a class="header-anchor" href="#etica-tecnologica-y-limites-de-seguridad" aria-label="Permalink to &quot;Ética Tecnológica y Límites de Seguridad&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>68</td></tr><tr><td>Módulo</td><td>Sistemas Tecnológicos y Energéticos</td></tr><tr><td>Palabras clave</td><td>Ética tecnológica, límites de seguridad, clasificación de riesgos por niveles, tecnologías prohibidas, revisión ética</td></tr></tbody></table><h2 id="i-los-principios-fundamentales-de-la-etica-tecnologica" tabindex="-1">I. Los Principios Fundamentales de la Ética Tecnológica <a class="header-anchor" href="#i-los-principios-fundamentales-de-la-etica-tecnologica" aria-label="Permalink to &quot;I. Los Principios Fundamentales de la Ética Tecnológica&quot;">​</a></h2><p>La ética tecnológica de la Civilización Simbiótica del Ancla se fundamenta en el valor esencial de la &quot;evolución simbiótica&quot;. Toda investigación, desarrollo y aplicación de tecnología debe responder una pregunta central: ¿esta tecnología promueve la evolución simbiótica de todos los seres, o proporciona nuevos medios para la depredación y el daño? Si la respuesta es lo segundo, sin importar cuán grande sea la eficacia individual de la tecnología, debe ser estrictamente limitada o prohibida.</p><p>Los principios fundamentales de la ética tecnológica incluyen tres:</p><ul><li><strong>El principio de no daño</strong>: la aplicación de la tecnología no debe causar daño innecesario a ninguna forma de vida, y no debe proporcionar herramientas para el cultivo depredador.</li><li><strong>El principio de ganancia simbiótica</strong>: el desarrollo de la tecnología debe apuntar a elevar el grado de simbiosis de toda la civilización, en lugar de meramente fortalecer las capacidades de unos pocos individuos.</li><li><strong>El principio de transparencia y trazabilidad</strong>: los procesos de investigación y desarrollo y los registros de aplicación de todas las tecnologías de nivel de ingeniería de leyes deben ser trazables y estar sujetos a revisión ética y supervisión pública.</li></ul><h2 id="ii-el-sistema-de-clasificacion-de-riesgos-tecnicos" tabindex="-1">II. El Sistema de Clasificación de Riesgos Técnicos <a class="header-anchor" href="#ii-el-sistema-de-clasificacion-de-riesgos-tecnicos" aria-label="Permalink to &quot;II. El Sistema de Clasificación de Riesgos Técnicos&quot;">​</a></h2><p>La civilización simbiótica ha establecido un estricto sistema de clasificación de riesgos técnicos, realizando evaluación de riesgos y gestión clasificada para todas las tecnologías de nivel de ingeniería de leyes:</p><table tabindex="0"><thead><tr><th>Nivel de riesgo</th><th>Nombre</th><th>Características</th><th>Requisitos de gestión</th></tr></thead><tbody><tr><td>R0</td><td>Sin riesgo</td><td>Tecnologías de la capa tecnológica de la realidad, sin manipulación de leyes</td><td>Gestión ordinaria, investigación y aplicación libres</td></tr><tr><td>R1</td><td>Riesgo bajo</td><td>Tecnologías de la capa de habilitación por leyes, mejoras de rendimiento de tecnologías existentes</td><td>Gestión por registro, debe pasar pruebas básicas de seguridad</td></tr><tr><td>R2</td><td>Riesgo medio</td><td>Tecnologías de la capa de ingeniería de leyes, que implican manipulación limitada de leyes</td><td>Gestión por licencia, debe pasar revisión ética y verificación en espacio aislado</td></tr><tr><td>R3</td><td>Riesgo alto</td><td>Implican operaciones de alto riesgo como reescritura espacial, intervención en la conciencia y fusión energética</td><td>Control estricto, investigación solo por instituciones autorizadas en espacios aislados de nivel S</td></tr><tr><td>R4</td><td>Nivel prohibido</td><td>Tecnologías que pueden causar colapso de plano, extinción de la conciencia o contaminación de leyes</td><td>Prohibición total de investigación y aplicación, conocimientos asociados clasificados como prohibidos</td></tr></tbody></table><p>Los niveles de riesgo no son inmutables. A medida que las tecnologías maduran y las medidas de seguridad mejoran, algunas tecnologías de nivel R3 pueden degradarse al nivel R2; a la inversa, si se descubren nuevos peligros de seguridad, las tecnologías también pueden someterse a un control reforzado.</p><h2 id="iii-limites-de-seguridad-clave" tabindex="-1">III. Límites de Seguridad Clave <a class="header-anchor" href="#iii-limites-de-seguridad-clave" aria-label="Permalink to &quot;III. Límites de Seguridad Clave&quot;">​</a></h2><p>La ética tecnológica y los límites de seguridad delimitan claramente las siguientes líneas rojas infranqueables:</p><h3 id="_3-1-limite-de-seguridad-energetica" tabindex="-1">3.1 Límite de seguridad energética <a class="header-anchor" href="#_3-1-limite-de-seguridad-energetica" aria-label="Permalink to &quot;3.1 Límite de seguridad energética&quot;">​</a></h3><ul><li>Se prohíben los experimentos de liberación de energía que superen la capacidad de carga del plano principal.</li><li>Se prohíbe la investigación y el desarrollo de tecnologías de extracción de energía destinadas a saquear la energía de otras formas de vida.</li><li>La investigación de la Energía Anómala debe realizarse en espacios aislados y debe seguir estrictamente el proceso de tratamiento de los tres tipos.</li></ul><h3 id="_3-2-limite-de-seguridad-espacial" tabindex="-1">3.2 Límite de seguridad espacial <a class="header-anchor" href="#_3-2-limite-de-seguridad-espacial" aria-label="Permalink to &quot;3.2 Límite de seguridad espacial&quot;">​</a></h3><ul><li>Se prohíben los experimentos de reescritura de leyes espaciales en estado no aislado.</li><li>La apertura de canales transplanar debe pasar una evaluación de seguridad, para prevenir daños permanentes a las barreras de plano.</li><li>La construcción y destrucción de espacios aislados deben seguir los protocolos estándar, sin dejar residuos espaciales.</li></ul><h3 id="_3-3-limite-de-seguridad-de-la-conciencia" tabindex="-1">3.3 Límite de seguridad de la conciencia <a class="header-anchor" href="#_3-3-limite-de-seguridad-de-la-conciencia" aria-label="Permalink to &quot;3.3 Límite de seguridad de la conciencia&quot;">​</a></h3><ul><li>Se prohíbe la investigación y el desarrollo de tecnologías no autorizadas de manipulación de la conciencia y alteración de la memoria.</li><li>La investigación sobre las Entidades Oscuras de Reemplazo debe cumplir con el Código de Ética del Alma Dual y las reglas de tratamiento de las cuatro ramas.</li><li>La tecnología de interfaz del dominio de la conciencia debe estar equipada con un mecanismo de disyuntor de seguridad irreversible.</li></ul><h3 id="_3-4-limite-de-seguridad-temporal" tabindex="-1">3.4 Límite de seguridad temporal <a class="header-anchor" href="#_3-4-limite-de-seguridad-temporal" aria-label="Permalink to &quot;3.4 Límite de seguridad temporal&quot;">​</a></h3><ul><li>Las operaciones de regresión temporal deben seguir estrictamente el principio de &quot;observar primero, interferir de manera limitada&quot;.</li><li>Se prohíbe cualquier experimento u operación que pueda causar paradojas temporales.</li><li>Los registros de regresión temporal deben estar sujetos a monitoreo continuo por el mecanismo de prevención y control de paradojas temporales.</li></ul><h2 id="iv-el-mecanismo-de-revision-etica" tabindex="-1">IV. El Mecanismo de Revisión Ética <a class="header-anchor" href="#iv-el-mecanismo-de-revision-etica" aria-label="Permalink to &quot;IV. El Mecanismo de Revisión Ética&quot;">​</a></h2><p>Para garantizar la implementación de la ética tecnológica, la civilización simbiótica ha establecido un mecanismo de revisión ética de múltiples niveles:</p><ol><li><strong>Revisión previa a la investigación</strong>: todos los proyectos de investigación y desarrollo de tecnologías de nivel R2 y superiores deben presentar una solicitud de revisión ética antes de comenzar, evaluando un Comité de Ética Tecnológica independiente sus riesgos y beneficios.</li><li><strong>Monitoreo durante el experimento</strong>: el proceso experimental de las tecnologías de nivel R3 debe tener un observador ético presente en todo momento; los datos experimentales se cargan en tiempo real al sistema de monitoreo ético de la red del Ancla.</li><li><strong>Evaluación previa a la aplicación</strong>: antes de que una nueva tecnología pase del laboratorio a la producción en masa, debe pasar una evaluación de seguridad independiente y una evaluación de impacto social.</li><li><strong>Seguimiento posterior a la aplicación</strong>: las tecnologías aplicadas continúan recibiendo seguimiento de seguridad; cuando se descubren nuevos problemas éticos, pueden iniciarse en cualquier momento procedimientos de reevaluación o incluso de retirada.</li><li><strong>Participación pública</strong>: las decisiones tecnológicas importantes deben pasar por procedimientos de audiencia pública, garantizando que la dirección del desarrollo tecnológico se ajuste a los intereses comunes de toda la civilización.</li></ol><h2 id="v-la-lista-de-tecnologias-prohibidas" tabindex="-1">V. La Lista de Tecnologías Prohibidas <a class="header-anchor" href="#v-la-lista-de-tecnologias-prohibidas" aria-label="Permalink to &quot;V. La Lista de Tecnologías Prohibidas&quot;">​</a></h2><p>Las siguientes tecnologías están explícitamente clasificadas como tecnologías prohibidas de nivel R4, con su investigación y desarrollo totalmente prohibidos:</p><ul><li>Armas de nivel de destrucción de planos: tecnologías de armas capaces de destruir la estructura espacial de un plano completo.</li><li>Dispositivos de extinción de la conciencia: tecnologías capaces de borrar o esclavizar en masa la conciencia de las formas de vida.</li><li>Motores de leyes depredadores: tecnologías que operan sobre el mecanismo de saquear sistemáticamente el origen de otras formas de vida.</li><li>Generadores de paradojas temporales: tecnologías que crean deliberadamente paradojas temporales para obtener beneficios indebidos.</li><li>Diseminadores de contaminación de leyes: tecnologías que difunden deliberadamente la contaminación de leyes para destruir otras civilizaciones.</li></ul><p>El conocimiento relacionado con las tecnologías prohibidas se almacena cifrado en el archivo prohibido del Ancla principal, y solo puede consultarse en caso de crisis de seguridad a nivel civilizacional, tras la autorización de la más alta autoridad de las instituciones de gobernanza simbiótica.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La ética tecnológica y los límites de seguridad son el &quot;sistema de frenos&quot; del sistema tecnológico de la Civilización Simbiótica del Ancla. Garantizan que el desarrollo de la tecnología sirva siempre al objetivo fundamental de la evolución simbiótica y no se convierta en nuevas herramientas de depredación. En una era donde las leyes pueden manipularse mediante ingeniería, los límites éticos son más importantes que la capacidad técnica — solo sosteniendo los límites puede la tecnología convertirse verdaderamente en un apoyo, y no una amenaza, para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>60-技术体系总览 (Visión General del Sistema Tecnológico)</li><li>19-修炼伦理与边界 (Ética y Límites del Cultivo)</li><li>88-跨位面伦理准则 (Código de Ética Transplanar)</li></ul>',31)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
